/**
 * ResFormer page figure: a sinus/AF toggle redraws a SYNTHETIC ECG trace and its R-R intervals.
 * Everything drawn here is generated by the functions below. It is an illustration of the two kinds of
 * information the model's branches see (waveform shape, beat timing), not data from the dataset.
 */
import { initProject, svgEl, htmlEl, buttonGroup, reducedMotion } from './common.js';

const WIDTH = 440;
const PX_PER_S = 62;
const BASE_Y = 72;
const AMP = 52;
const RHYTHMS = Object.freeze({
  sinus: { rr: [0.84, 0.86, 0.85, 0.84, 0.86, 0.85, 0.84, 0.85], pWave: true, wobble: 0,
    wave: 'P wave before every beat', timing: 'Evenly spaced beats',
    read: 'Sinus rhythm: the beats are evenly spaced and each is preceded by a small P wave. The R-R branch sees almost no spread.' },
  af: { rr: [0.52, 0.93, 0.61, 1.08, 0.57, 0.84, 0.69, 0.48, 0.97, 0.64], pWave: false, wobble: 0.05,
    wave: 'No clear P waves, wobbling baseline', timing: 'Uneven beats',
    read: 'Atrial fibrillation: no organised P waves and beats arrive at irregular intervals. That irregularity is the signal the R-R branch carries.' },
});

const bump = (t, centre, width, height) => height * Math.exp(-(((t - centre) / width) ** 2));

function peaks(rr) {
  return rr.reduce((acc, gap) => [...acc, acc[acc.length - 1] + gap], [0.3]);
}

function sample(t, beats, rhythm) {
  let y = rhythm.wobble ? rhythm.wobble * (Math.sin(t * 31) + 0.6 * Math.sin(t * 53 + 1)) : 0;
  beats.forEach((r) => {
    if (rhythm.pWave) y += bump(t, r - 0.17, 0.035, 0.14);
    y += bump(t, r - 0.035, 0.012, -0.12) + bump(t, r, 0.014, 1) + bump(t, r + 0.035, 0.014, -0.2) + bump(t, r + 0.27, 0.06, 0.26);
  });
  return y;
}

export function stdDevMs(rr) {
  const mean = rr.reduce((a, b) => a + b, 0) / rr.length;
  return Math.sqrt(rr.reduce((a, b) => a + (b - mean) ** 2, 0) / rr.length) * 1000;
}

function render(svg, key, animate) {
  const rhythm = RHYTHMS[key];
  const beats = peaks(rhythm.rr).filter((t) => t * PX_PER_S < WIDTH - 6);
  const points = [];
  for (let px = 0; px <= WIDTH; px += 1) points.push(`${px},${(BASE_Y - sample(px / PX_PER_S, beats, rhythm) * AMP).toFixed(1)}`);
  svg.replaceChildren(svg.querySelector('title'), svg.querySelector('desc') || svgEl('desc'));
  [0, 1, 2, 3, 4, 5, 6, 7].forEach((s) => svg.append(svgEl('line', { class: 'grid', x1: s * PX_PER_S, x2: s * PX_PER_S, y1: 0, y2: 120 })));
  const trace = svgEl('polyline', { class: `trace${animate ? ' draw' : ''}`, points: points.join(' '), pathLength: 1 });
  svg.append(trace);
  const gaps = beats.slice(1).map((t, i) => t - beats[i]);
  gaps.forEach((gap, i) => {
    const h = gap * 38;
    svg.append(svgEl('rect', { class: 'rr', x: beats[i] * PX_PER_S + 2, y: 186 - h, width: Math.max(2, gap * PX_PER_S - 4), height: h }));
  });
  const label = svgEl('text', { x: 4, y: 138 });
  label.textContent = `R-R intervals, spread (std dev) ${stdDevMs(gaps).toFixed(0)} ms`;
  svg.append(label);
  return rhythm;
}

function init() {
  const svg = document.getElementById('ecg-svg');
  const box = document.getElementById('ecg-rhythm');
  if (!svg || !box) return;
  const animate = !reducedMotion();
  buttonGroup(box, '[data-rhythm]', (button) => {
    const rhythm = render(svg, button.dataset.rhythm, animate);
    document.getElementById('ecg-wave').textContent = rhythm.wave;
    document.getElementById('ecg-rr').textContent = rhythm.timing;
    document.getElementById('ecg-read').replaceChildren(htmlEl('p', {}, rhythm.read));
  })(box.querySelector('[data-rhythm="sinus"]'));
}

initProject();
init();
